#include "ir_helpers.h"
#include "optimizer_helpers.h"
#include "optimizer_loop_internal.h"

/**
 * @brief Evaluate the loop's ordered bound test for a concrete index.
 *
 * @param type IR operation or comparison type.
 * @param current Current induction value.
 * @param end Loop bound.
 * @return Whether the current value satisfies the range comparison.
 */
static bool range_test(IrInstructionType type, IrInt current, IrInt end) {
  switch (type) {
    case IR_INST_LT:
      return current < end;
    case IR_INST_LE:
      return current <= end;
    case IR_INST_GT:
      return current > end;
    case IR_INST_GE:
      return current >= end;
    default:
      return false;
  }
}

bool optimizer_loop_unroll_range(Ctx* ctx,
                                 IrFunctionId fid,
                                 IrBlockId pre_id,
                                 IrBlockId head_id,
                                 IrBlockId test_id,
                                 IrBlockId entry,
                                 IrBlockId latch_id) {
  IrFunction* fn = &ctx->ir.functions.data[fid];
  IrBlock* pre = &fn->blocks.data[pre_id];
  IrBlock* head = &fn->blocks.data[head_id];
  IrBlock* test = &fn->blocks.data[test_id];
  IrBlockId exit = test->terminator.value.conditional_target.false_target;
  IrInstructionArray* latch = &fn->blocks.data[latch_id].instructions;

  if (latch->count != 2 || (head == test && head->instructions.count != 2) ||
      (head != test &&
       (head->instructions.count != 1 || test->instructions.count != 1)))
    return false;

  IrInstruction load = head->instructions.data[0];
  IrInstruction cmp = test->instructions.data[test->instructions.count - 1];
  IrInstruction next = latch->data[0];
  IrInstruction store = latch->data[1];

  if (load.type != IR_INST_LOAD || cmp.type < IR_INST_LT ||
      cmp.type > IR_INST_GE ||
      !optimizer_loop_direct_use(
          test->terminator.value.conditional_target.condition, cmp.result) ||
      !optimizer_loop_direct_use(cmp.operands.binary.left, load.result) ||
      cmp.operands.binary.right.type != IR_OP_INT32 ||
      next.type != IR_INST_ADD ||
      !optimizer_loop_direct_use(next.operands.binary.left, load.result) ||
      next.operands.binary.right.type != IR_OP_INT32 ||
      store.type != IR_INST_STORE ||
      store.operands.store.target != load.operands.load.source ||
      !optimizer_loop_direct_use(store.operands.store.source, next.result))
    return false;

  IrStackSlotId slot = load.operands.load.source;
  const IrOperand* start = NULL;
  for (size_t i = 0; i < pre->instructions.count; i++) {
    const IrInstruction* inst = &pre->instructions.data[i];
    if (inst->type == IR_INST_STORE && inst->operands.store.target == slot)
      start = &inst->operands.store.source;
  }

  if (!start || start->type != IR_OP_INT32)
    return false;

  // Compute the trip count without executing the loop and check the final
  // advance for overflow.
  IrInt current = start->value.int32_value;
  IrInt end = cmp.operands.binary.right.value.int32_value;
  IrInt step = next.operands.binary.right.value.int32_value;
  if (current < INT32_MIN || current > INT32_MAX || end < INT32_MIN ||
      end > INT32_MAX || step < INT32_MIN || step > INT32_MAX || step == 0)
    return false;

  bool descending = cmp.type == IR_INST_GT || cmp.type == IR_INST_GE;
  if ((step < 0) != descending)
    return false;

  IrInt stride = descending ? -step : step;
  IrInt distance = descending ? current - end : end - current;
  bool inclusive = cmp.type == IR_INST_GE || cmp.type == IR_INST_LE;
  uint64_t trips = 0;
  if (range_test(cmp.type, current, end))
    trips = (uint64_t)((distance + (inclusive ? stride : stride - 1)) / stride);

  // The last advance must also fit the source integer domain.
  IrInt final = current + (IrInt)trips * step;
  if (final < INT32_MIN || final > INT32_MAX)
    return false;

  // Prove the copied region has no escaping values or other writes to the
  // induction slot.
  RangeBody body = {.blocks = {entry}, .count = 1, .latch = latch_id};
  if (!optimizer_loop_collect_range_body(fn, &body, pre_id, head_id, test_id,
                                         exit))
    return false;

  bool linear = body.count == 1 &&
                optimizer_loop_jumps_to(&fn->blocks.data[entry], latch_id);
  bool partial = trips > MAX_RANGE_TRIPS;
  if ((partial && (!linear || body.instructions > 8)) ||
      (!partial && trips * (body.instructions + body.count) > 64))
    return false;

  size_t* uses = ctx->optimizer.value_data;
  optimizer_count_value_uses(fn, uses);
  if (uses[cmp.result] != 1 || uses[next.result] != 1 ||
      uses[load.result] !=
          2 + optimizer_loop_region_uses(fn, &body, load.result))
    return false;

  for (size_t b = 0; b < body.count; b++) {
    IrInstructionArray* instructions =
        &fn->blocks.data[body.blocks[b]].instructions;

    for (size_t i = 0; i < instructions->count; i++) {
      const IrInstruction* inst = &instructions->data[i];

      if (inst->type == IR_INST_STORE && inst->operands.store.target == slot)
        return false;

      if (inst->result != IR_INVALID_ID &&
          uses[inst->result] !=
              optimizer_loop_region_uses(fn, &body, inst->result))
        return false;
    }
  }

  // Choose the smallest expansion first, then fall back to pairing or cloning
  // the full fixed trip count.
  if (linear &&
      optimizer_loop_fold_range_sum(ctx, fid, pre_id, &body, exit, load.result,
                                    slot, current, step, trips, final))
    return true;

  // AI generated by: Codex (GPT-6.2-sol)
  // Prompt: "Implement"
  // Changes: Use an equality exit when the proven paired induction lands on the
  // bound.
  if (partial) {
    // The unroller peels an odd first trip, so pairs can land exactly on end.
    if (final == end && !inclusive)
      test->instructions.data[test->instructions.count - 1].type = IR_INST_NE;

    optimizer_loop_unroll_range_by_two(ctx, fid, pre_id, &body, load.result,
                                       slot, current, step, trips, next.result);
    return true;
  }

  IrBlockId first = fn->blocks.count;
  IrBlockId finish = pre_id;
  if (!linear && trips) {
    for (size_t i = 0; i < trips * body.count; i++)
      ir_add_block(ctx, fid);

    // Use a separate finish block when iteration copies have internal branches.
    finish = ir_add_block(ctx, fid);
    fn->blocks.data[pre_id].terminator.value.jump_target = first;
  }

  // Use fresh value IDs for each cloned iteration and pass its index as a
  // constant.
  size_t original_values = fn->value_count;
  for (size_t t = 0; t < trips; t++) {
    size_t offset = fn->value_count;
    IrBlockId iteration = first + t * body.count;

    for (size_t b = 0; b < body.count; b++) {
      IrBlockId target = linear ? pre_id : iteration + b;
      IrBlockId source = body.blocks[b];

      optimizer_loop_clone_iteration_block(
          ctx, fid, target, source, &body, load.result, slot,
          (IrOperand){IR_OP_INT32, {.int32_value = current + (IrInt)t * step}},
          offset);

      if (linear)
        continue;

      IrBlockTerminator term = fn->blocks.data[source].terminator;
      if (term.type == IR_TERMINATOR_JUMP)
        term.value.jump_target = optimizer_loop_iteration_target(
            &body, iteration, term.value.jump_target);

      if (term.type == IR_TERMINATOR_CONDITIONAL) {
        term.value.conditional_target.true_target =
            optimizer_loop_iteration_target(
                &body, iteration, term.value.conditional_target.true_target);
        term.value.conditional_target.false_target =
            optimizer_loop_iteration_target(
                &body, iteration, term.value.conditional_target.false_target);
      }

      IrOperand* operand = optimizer_loop_terminator_operand(&term);

      if (operand)
        optimizer_loop_substitute_iteration(
            fn, &body, operand, load.result, slot,
            (IrOperand){IR_OP_INT32,
                        {.int32_value = current + (IrInt)t * step}},
            offset);

      ir_set_terminator(ctx, fid, target, term);
    }

    fn->value_count = offset + original_values;
  }

  optimizer_loop_store_induction(
      ctx, fid, finish, slot, (IrOperand){IR_OP_INT32, {.int32_value = final}});
  ir_set_terminator(ctx, fid, finish,
                    (IrBlockTerminator){.type = IR_TERMINATOR_JUMP,
                                        .value.jump_target = exit});
  return true;
}

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement. You can change IR if it improves the results/makes things
// more clear. Also try to split long files (300+) into smaller thematic ones,
// like optimizer was before" Changes: Give counted while loops the same latch
// shape as counted ranges.
IrBlockId optimizer_loop_split_counted_while(Ctx* ctx,
                                             IrFunctionId fid,
                                             IrBlockId head,
                                             IrBlockId body) {
  IrFunction* fn = &ctx->ir.functions.data[fid];
  IrInstructionArray* header = &fn->blocks.data[head].instructions;
  IrInstructionArray* loop = &fn->blocks.data[body].instructions;

  if (header->count != 2 || loop->count < 2 ||
      header->data[0].type != IR_INST_LOAD ||
      header->data[0].result_type != IR_INT)
    return IR_INVALID_ID;

  IrInstruction load = header->data[0];
  IrInstruction cmp = header->data[1];
  size_t suffix = loop->count - 2;
  IrInstruction add = loop->data[suffix];
  IrInstruction store = loop->data[suffix + 1];
  IrStackSlotId slot = load.operands.load.source;

  if (cmp.type < IR_INST_LT || cmp.type > IR_INST_GE ||
      !optimizer_loop_direct_use(cmp.operands.binary.left, load.result) ||
      cmp.operands.binary.right.type != IR_OP_INT32 ||
      add.type != IR_INST_ADD ||
      add.operands.binary.right.type != IR_OP_INT32 ||
      store.type != IR_INST_STORE || store.operands.store.target != slot ||
      !optimizer_loop_direct_use(store.operands.store.source, add.result))
    return IR_INVALID_ID;

  bool same_value =
      optimizer_loop_direct_use(add.operands.binary.left, load.result);

  for (size_t i = 0; i < suffix; i++) {
    const IrInstruction* inst = &loop->data[i];
    if (inst->type == IR_INST_STORE && inst->operands.store.target == slot)
      return IR_INVALID_ID;

    if (inst->type == IR_INST_LOAD && inst->operands.load.source == slot &&
        optimizer_loop_direct_use(add.operands.binary.left, inst->result))
      same_value = true;
  }

  if (!same_value)
    return IR_INVALID_ID;

  IrBlockId latch = ir_add_block(ctx, fid);
  IrBlock* original = &fn->blocks.data[body];
  IrBlock* advance = &fn->blocks.data[latch];
  add.operands.binary.left = (IrOperand){IR_OP_VALUE, {.id = load.result}};
  // These two instructions own no heap operands.
  array_append(ctx, &advance->instructions, add);
  array_append(ctx, &advance->instructions, store);
  original->instructions.count -= 2;
  advance->terminator = original->terminator;
  original->terminator.value.jump_target = latch;
  return latch;
}
